  static Sprite Load(string p){var s=AssetDatabase.LoadAssetAtPath<Sprite>(p);if(!s)throw new InvalidOperationException(p);return s;}
  public static void Import(){foreach(string folder in Folders){foreach(string sub in new[]{"Meshes","Materiais"})if(!AssetDatabase.IsValidFolder(folder+sub))AssetDatabase.CreateFolder(folder.TrimEnd('/'),sub);foreach(var path in AssetDatabase.FindAssets("t:Texture2D",new[]{folder.TrimEnd('/')}).Select(AssetDatabase.GUIDToAssetPath)){var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.spritePixelsPerUnit=100;i.alphaIsTransparency=true;i.mipmapEnabled=false;i.filterMode=FilterMode.Bilinear;i.wrapMode=TextureWrapMode.Clamp;i.maxTextureSize=4096;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();}}}
  static void Layer(FarolParallaxLayer l,string path,float scale,float center,int order,Color color,float overlap=.9f){var s=Load(path);l.gameObject.SetActive(true);l.width=s.bounds.size.x*scale*overlap;l.verticalCenter=center;l.mirrorRepeat=true;l.fadeDistance=5;l.fadeIn=true;l.fadeOut=true;foreach(var p in l.panels){p.sprite=s;p.transform.localScale=Vector3.one*scale;p.color=color;p.sortingOrder=order;}}
  static void Platform(FarolSourceMarker m,JToken row,bool cave){var source=m.GetComponent<SpriteRenderer>();var collider=m.GetComponent<Collider2D>();if(!source||!collider)throw new InvalidOperationException(m.name);var s=Load((string)row["asset_unity"]);float scale=collider.bounds.size.x/(s.rect.width/100-.04f);var old=m.transform.Find("Laje HQ — visual");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var child=new GameObject("Laje HQ — visual");child.transform.position=new Vector3(collider.bounds.center.x,collider.bounds.max.y+((float)row["apoio_y"]/100-s.bounds.size.y*.5f)*scale);child.transform.localScale=Vector3.one*scale;child.transform.SetParent(m.transform,true);var visual=child.AddComponent<SpriteRenderer>();visual.sprite=s;visual.sharedMaterial=source.sharedMaterial;visual.sortingOrder=source.sortingOrder+1;visual.sortingLayerID=source.sortingLayerID;if(cave)source.color=new Color(.65f,.83f,1);var proxy=m.GetComponent<FarolPlatformArt>();if(!proxy)proxy=m.gameObject.AddComponent<FarolPlatformArt>();proxy.source=source;proxy.visual=visual;proxy.surface=m.GetComponent<FarolIslandSurface>();proxy.animator=m.GetComponent<Animator>();source.forceRenderingOff=true;}
  static void Suspension(FarolSourceMarker marker,JToken definition){if(definition["ropeTopY"]==null)return;var b=marker.GetComponent<Collider2D>().bounds;float top=(1080-(float)definition["ropeTopY"])/100;var art=marker.GetComponent<FarolHangingPlatformArt>();if(!art)art=marker.gameObject.AddComponent<FarolHangingPlatformArt>();art.support=marker.GetComponent<Collider2D>();art.leftAnchor=new Vector3(b.min.x+.22f,top);art.rightAnchor=new Vector3(b.max.x-.22f,top);LineRenderer Line(string name){var old=marker.transform.Find(name);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var go=new GameObject(name);go.transform.SetParent(marker.transform,false);var l=go.AddComponent<LineRenderer>();l.useWorldSpace=true;l.positionCount=2;l.sharedMaterial=AssetDatabase.GetBuiltinExtraResource<Material>("Sprites-Default.mat");l.startWidth=l.endWidth=.06f;l.startColor=l.endColor=new Color(.55f,.4f,.21f);l.sortingOrder=10;return l;}art.left=Line("Corda de sustentação esquerda");art.right=Line("Corda de sustentação direita");art.left.SetPosition(0,art.leftAnchor);art.left.SetPosition(1,new Vector3(b.min.x+.22f,b.max.y));art.right.SetPosition(0,art.rightAnchor);art.right.SetPosition(1,new Vector3(b.max.x-.22f,b.max.y));}
  static void Fill(Transform root,Bounds b,string folder,string texture,int index,bool pilot){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(texture);float unitX=tex.width/100f,unitY=tex.height/100f;var vs=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();for(int x=Mathf.FloorToInt(b.min.x/unitX);x<Mathf.CeilToInt(b.max.x/unitX);x++)for(int y=Mathf.FloorToInt(b.min.y/unitY);y<Mathf.CeilToInt((b.max.y-.16f)/unitY);y++){float x0=Mathf.Max(b.min.x,x*unitX),x1=Mathf.Min(b.max.x,(x+1)*unitX),y0=Mathf.Max(b.min.y,y*unitY),y1=Mathf.Min(b.max.y-.16f,(y+1)*unitY);if(y1<=y0)continue;int n=vs.Count;vs.AddRange(new[]{new Vector3(x0,y0),new Vector3(x1,y0),new Vector3(x0,y1),new Vector3(x1,y1)});uv.AddRange(new[]{new Vector2(Mathf.PingPong(x0/unitX,1),Mathf.PingPong(y0/unitY,1)),new Vector2(Mathf.PingPong(x1/unitX,1),Mathf.PingPong(y0/unitY,1)),new Vector2(Mathf.PingPong(x0/unitX,1),Mathf.PingPong(y1/unitY,1)),new Vector2(Mathf.PingPong(x1/unitX,1),Mathf.PingPong(y1/unitY,1))});tris.AddRange(new[]{n,n+2,n+1,n+1,n+2,n+3});}var mesh=new Mesh{name="Preenchimento_"+index};mesh.SetVertices(vs);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);mesh.RecalculateBounds();string path=folder+"Meshes/Preenchimento_"+index+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}else{saved=mesh;AssetDatabase.CreateAsset(mesh,path);}string mp=folder+"Materiais/Material_"+(pilot?"URP":"Padrao")+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!material){material=new Material(Shader.Find(pilot?"Universal Render Pipeline/2D/Sprite-Unlit-Default":"Sprites/Default"));AssetDatabase.CreateAsset(material,mp);}material.mainTexture=tex;EditorUtility.SetDirty(material);var go=new GameObject("Alvenaria ou rocha natural "+index);go.transform.SetParent(root,false);go.AddComponent<MeshFilter>().sharedMesh=saved;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.sortingOrder=4;}
  public static string Apply(){if(EditorApplication.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Salve e saia do Play.");foreach(var path in new[]{"Assets/Farol/Campanha_20261021_215901/Fase3_Ilha.unity","Assets/Farol/Visual/Bloco01/Fase3_Referencia.unity"}){
   var scene=EditorSceneManager.OpenScene(path);bool pilot=path.Contains("Referencia");var old=GameObject.Find("Gruta, copas e ruínas — HQ");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Gruta, copas e ruínas — HQ");var ranges=root.AddComponent<FarolIslandSceneryRanges>();
   foreach(var l in UnityEngine.Object.FindObjectsByType<FarolParallaxLayer>(FindObjectsInactive.Include,FindObjectsSortMode.None)){
    if(l.x0==0&&l.name=="Fundo camada 0")l.x1=1075.2f;
    bool k=Mathf.Abs(l.x0-768)<.01f,ll=Mathf.Abs(l.x0-806.4f)<.01f,m=Mathf.Abs(l.x0-883.2f)<.01f,n=Mathf.Abs(l.x0-960)<.01f,o=Mathf.Abs(l.x0-1036.8f)<.01f;if(!k&&!ll&&!m&&!n&&!o)continue;
    if(k&&l.name=="Fundo camada 3")Layer(l,Folders[0]+"camadas/cenarioK_3.png",1.1f,5.94f,-27,Color.white,1);
    else if(ll&&l.name=="Fundo camada 1"){Layer(l,FarolForestArtIntegration.Folder+"camadas/mata_distante_revisada.png",1.3f,8.04f,-43,new Color(.82f,.9f,.9f),1);l.x1=1075.2f;}
    else if(ll&&l.name=="Fundo camada 3"){Layer(l,FarolDEArtIntegration.E+"camadas/cenarioE_3_mata_densa.png",1,6.6f,-31,new Color(.62f,.73f,.66f));l.x1=1036.8f;ranges.forest=l;}
    else if(n&&l.name=="Fundo camada 2")Layer(l,Folders[3]+"camadas/ruinas_distantes.png",1,5.4f,-30,Color.white,1);
    else if(o&&l.name=="Fundo camada 3")Layer(l,FarolHIJArtIntegration.J+"camadas/cenarioJ_3_paredao_SEM_AGUA.png",1.4f,7.62f,-29,new Color(.75f,.85f,.84f),.84f);
    else l.gameObject.SetActive(false);
   }
   // Monumento único no mirante de O1, em coordenadas do mundo.
   var cave=new GameObject("Entrada única da caverna azul");cave.transform.SetParent(root.transform,false);cave.transform.position=new Vector3(1065.6f,5.4f);var cv=cave.AddComponent<SpriteRenderer>();cv.sprite=Load(Folders[4]+"camadas/cenarioO_3.png");cv.sortingOrder=-26;
   var markers=UnityEngine.Object.FindObjectsByType<FarolSourceMarker>(FindObjectsSortMode.None);var map=JObject.Parse(UnityEngine.Object.FindFirstObjectByType<FarolIslandMechanics>().map.text);
   for(int si=0;si<5;si++){string sector=((char)('K'+si)).ToString(),folder=Folders[si];float offset=si==0?768:si==1?806.4f:si==2?883.2f:si==3?960:1036.8f;var manifest=JArray.Parse(System.IO.File.ReadAllText(folder+"MANIFESTO.json"));var application=JObject.Parse(System.IO.File.ReadAllText(folder+"APLICACAO.json"));int index=0;
    foreach(var marker in markers.Where(m=>m.sector==sector&&m.category=="ground").OrderBy(m=>m.transform.position.x).ThenBy(m=>m.transform.position.y)){var c=marker.GetComponent<Collider2D>();if(!c)continue;var b=c.bounds;foreach(var sr in marker.GetComponentsInChildren<SpriteRenderer>())sr.enabled=false;bool rock=marker.name.Contains("rock"),roof=(sector=="M"||sector=="N")&&b.size.y<.5f;int id=index++;if(!roof){int first=root.transform.childCount;FarolBeachArtIntegration.Ground(root.transform,b,rock,id,pilot,rock?FarolCoastArtIntegration.Folder:FarolForestArtIntegration.Folder,rock?"rocha_umida_topo":"terra_grama_topo",rock?"rocha_umida_meio":"terra_meio",meshFolder:folder);if(sector=="K"||sector=="N"||sector=="O"){for(int q=first;q<root.transform.childCount;q++){var t=root.transform.GetChild(q);if(t.name.EndsWith("_Base"))t.GetComponent<MeshRenderer>().enabled=false;if(sector=="K"){var mesh=t.GetComponent<MeshFilter>().sharedMesh;var colors=mesh.colors;for(int v=0;v<colors.Length;v++){colors[v].r*=.65f;colors[v].g*=.83f;}mesh.colors=colors;EditorUtility.SetDirty(mesh);}}Fill(root.transform,b,folder,Folders[3]+"pecas/material_"+(sector=="K"?"gruta":"ruinas")+".png",id,pilot);}}
     var entry=manifest.FirstOrDefault(e=>e["posicao"]!=null&&!((string)e["arquivo"]).Contains("breakables")&&Mathf.Abs((float)e["posicao"][0]/100+offset-b.min.x)<.03f&&Mathf.Abs((1080-(float)e["posicao"][1])/100-b.max.y)<.03f);if(entry!=null)FarolDEArtIntegration.Panel(root.transform,b,folder+((string)entry["arquivo"]).Replace(".png",""));
    }
    foreach(var marker in markers.Where(m=>m.sector==sector&&m.category=="platforms")){var d=JObject.Parse(marker.originalJson);var row=application["plataformas"].FirstOrDefault(e=>Mathf.Abs((float)e["dados_mapa"]["x"]/100+offset-(float)d["x"]/100)<.03f&&Mathf.Abs((float)e["dados_mapa"]["y"]-(float)d["y"])<.1f);if(row==null)throw new InvalidOperationException("Apoio sem arte: "+sector+" "+d["x"]);Platform(marker,row,sector=="K");var definition=map["chunks"].SelectMany(c=>c["platforms"]??new JArray()).FirstOrDefault(e=>Mathf.Abs((float)e["x"]-(float)d["x"])<.1f&&Mathf.Abs((float)e["y"]-(float)d["y"])<.1f);if(definition!=null)Suspension(marker,definition);}
    foreach(var marker in markers.Where(m=>m.sector==sector&&m.category=="decor")){var d=JObject.Parse(marker.originalJson);var row=application["decor"].FirstOrDefault(e=>Mathf.Abs((float)e["dados_mapa"]["x"]/100+offset-(float)d["x"]/100)<.03f&&((string)e["dados_mapa"]["kind"])==((string)d["kind"]));if(row==null)continue;var sr=marker.GetComponent<SpriteRenderer>();if(!sr)continue;string kind=(string)d["kind"];if(kind=="hollow_log"){sr.enabled=false;continue;}sr.sprite=Load((string)row["asset_unity"]);float scale=(float)row["escala_uniforme"];marker.transform.localScale=Vector3.one*scale;sr.flipX=(bool?)d["flip"]??false;marker.transform.position=new Vector3((float)d["x"]/100,(1080-(float)d["y"])/100+sr.sprite.bounds.size.y*scale*.5f);sr.color=Color.white;sr.sortingOrder=kind=="tree"||kind=="vine"||kind=="ruin_arch"||kind=="ruin_pillar"?-4:12;
     foreach(var secret in map["chunks"].Where(c=>(string)c["sector"]==sector).SelectMany(c=>c["secrets"]??new JArray())){float x=((float)secret["zone"]["x"]+(float)secret["zone"]["w"]/2)/100;if(Mathf.Abs(marker.transform.position.x-x)<3){var fade=marker.GetComponent<FarolSecretSceneryFade>();if(!fade)fade=marker.gameObject.AddComponent<FarolSecretSceneryFade>();fade.visual=sr;fade.secretId=(string)secret["id"];fade.centerX=x;}}
    }
   }
