   var player=UnityEngine.Object.FindFirstObjectByType<FarolPlayerController>();if(player&&player.useBiaAnimations)player.crouchingHeight=Mathf.Min(player.crouchingHeight,.88f);
   var fg=UnityEngine.Object.FindFirstObjectByType<FarolBeachForeground>();if(fg){fg.sectorEnd=1075.2f;ranges.foreground=fg;}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  }FarolVisualBlockOne.OpenCampaign();AssetDatabase.SaveAssets();return "K/L/M/N/O aplicados nas duas cenas.";}
